import pandas as pd

def find_eligible_users(purchases: pd.DataFrame, startDate: str, endDate: str, minAmount: int) -> pd.DataFrame:
    filtered = purchases[(purchases['time_stamp'] >= startDate) &
                         (purchases['time_stamp'] <= endDate) &
                         (purchases['amount'] >= minAmount)]
    return filtered[['user_id']].drop_duplicates().sort_values('user_id')
